import { validator } from '../clone/src/validator'
import { methodOverride } from '../clone/src/middleware/method-override'
import { cloneRawRequest } from '../clone/src/request'

const run = async (name: string, fn: () => Promise<unknown>) => {
  try {
    console.log(name, '=>', JSON.stringify(await fn()))
  } catch (e) {
    console.log(name, 'THREW', String(e))
  }
