const mkMultipart = () => {
  const fd = new FormData()
  fd.append('foo', 'bar')
  return new Request('http://localhost/', { method: 'POST', body: fd })
}

// validator json variants
const app = new Hono()
app.post('/json', validator('json', (v) => v), (c) => c.json(c.req.valid('json')))
app.post('/form', validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form'), p: await c.req.parseBody() }))
app.onError((e, c) => c.text('ERR ' + String(e), 500))
for (const ct of ['Application/JSON', 'APPLICATION/VND.API+JSON', 'application/json ; charset=utf-8', 'Application/JSON;Charset=UTF-8']) {
  await run('json ' + ct, async () => {
    const res = await app.request('/json', { method: 'POST', body: '{"a":1}', headers: { 'Content-Type': ct } })
    return [res.status, await res.text()]
  })
}
for (const ct of ['Application/X-WWW-Form-Urlencoded', 'application/x-www-form-urlencoded ; charset=utf-8', 'APPLICATION/X-WWW-FORM-URLENCODED;CHARSET=UTF-8']) {
  await run('form ' + ct, async () => {
    const res = await app.request('/form', { method: 'POST', body: 'a=1', headers: { 'Content-Type': ct } })
    return [res.status, await res.text()]
  })
}
await run('form multipart Boundary= uppercase param name', async () => {
  const src = mkMultipart()
  const ct = src.headers.get('content-type')!.replace('multipart/form-data; boundary=', 'Multipart/Form-Data; Boundary=')
  const res = await app.request('/form', { method: 'POST', body: await src.arrayBuffer(), headers: { 'Content-Type': ct } })
  return [ct, res.status, await res.text()]
})

// method override with mixed case
const app2 = new Hono()
app2.use('/posts', methodOverride({ app: app2 }))
app2.delete('/posts', (c) => c.text('DELETED'))
app2.post('/posts', async (c) => c.json({ posted: await c.req.parseBody() }))
for (const ct of ['application/x-www-form-urlencoded', 'Application/X-WWW-Form-Urlencoded']) {
  await run('methodOverride ' + ct, async () => {
    const res = await app2.request('/posts', { method: 'POST', body: '_method=DELETE&a=1', headers: { 'Content-Type': ct } })
    return [res.status, await res.text()]
  })
}

// cloneRawRequest after parseBody
const app3 = new Hono()
app3.post('/', async (c) => {
  const p = await c.req.parseBody()
  const cloned = await cloneRawRequest(c.req)
  const fd = await cloned.formData()
  return c.json({ p, cloned: [...fd.entries()], keys: Object.keys(c.req.bodyCache) })
})
app3.onError((e, c) => c.text('ERR ' + String(e), 500))
await run('cloneRawRequest after parseBody multipart', async () => {
  const res = await app3.request(mkMultipart())
  return [res.status, await res.text()]
})
